+                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
+                        @onclick="() => SelectChannelAsync(channel)">
+                        <div class="channel-name"># @channel.Name</div>
+                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
+                        @if (channel.UnreadCount > 0)
+                        {
+                            <span class="unread-badge">@channel.UnreadCount</span>
+                        }
+                    </li>
+                }
+            }
+        </ul>
+    </aside>
+
+    @* ── Main Message Area ── *@
+    <section class="message-area @(_threadOpen ? "thread-open" : "")">
+        @if (_activeChannel is not null)
+        {
+            <div class="message-header">
+                <h3># @_activeChannel.Name</h3>
+                <span class="channel-description">@_activeChannel.Description</span>
+            </div>
+
+            <div class="message-list" @ref="_messageListRef" @onscroll="HandleScrollAsync">
+                @if (_loadingOlder)
+                {
+                    <div class="loading-indicator">Loading older messages…</div>
+                }
+                @if (_messages is not null)
+                {
+                    @foreach (var msg in _messages)
+                    {
+                        <div class="message-bubble" @onmouseover="() => _hoveredMessageId = msg.Id"
+                             @onmouseout="() => { if (_hoveredMessageId == msg.Id) _hoveredMessageId = null; }">
+                            <div class="message-meta">
+                                <span class="author">@msg.Author</span>
+                                <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
+                            </div>
+                            <div class="message-content">@msg.Content</div>
+
+                            @* Reactions *@
+                            @if (msg.Reactions.Count > 0)
+                            {
+                                <div class="reactions-row">
+                                    @foreach (var r in msg.Reactions)
+                                    {
+                                        <button class="reaction-badge" title="@string.Join(", ", r.Users)"
+                                                @onclick="() => ToggleReactionAsync(msg.Id, r.Emoji)">
+                                            @r.Emoji @r.Users.Count
+                                        </button>
+                                    }
+                                </div>
+                            }
+
+                            @* Thread starter link *@
+                            @if (_threadSummaries.TryGetValue(msg.Id, out var summary))
+                            {
+                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg)">
+                                    @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
+                                    &middot; Last @FormatRelativeTime(summary.LastReplyAt)
+                                </button>
+                            }
+
+                            @* Hover action buttons *@
+                            @if (_hoveredMessageId == msg.Id)
+                            {
+                                <div class="message-actions">
+                                    <button class="action-btn" title="Reply in thread"
+                                            @onclick="() => OpenThreadAsync(msg)">💬 Reply</button>
+                                    <div class="emoji-picker-wrapper">
+                                        <button class="action-btn" title="Add reaction"
+                                                @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
+                                        @if (_emojiPickerMessageId == msg.Id)
+                                        {
+                                            <div class="emoji-picker">
+                                                @foreach (var emoji in _commonEmojis)
+                                                {
+                                                    <button class="emoji-option"
+                                                            @onclick="() => AddReactionAsync(msg.Id, emoji)">
+                                                        @emoji
+                                                    </button>
+                                                }
+                                            </div>
+                                        }
+                                    </div>
+                                </div>
+                            }
+                        </div>
+                    }
+                }
+            </div>
+
+            <div class="message-input-area">
+                <textarea @bind="_newMessageText" @bind:event="oninput"
+                          @onkeydown="HandleMessageKeyDown"
+                          placeholder="Type a message…" rows="2"></textarea>
+                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
+                    Send
+                </button>
+            </div>
+        }
+        else
+        {
+            <div class="no-channel-selected">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </section>
+
+    @* ── Right Panel: Thread View ── *@
+    @if (_threadOpen && _threadRootMessage is not null)
+    {
+        <aside class="thread-panel">
+            <div class="thread-header">
+                <h3>Thread</h3>
+                <button class="close-btn" @onclick="CloseThread" title="Close thread">✕</button>
+            </div>
+
+            <div class="thread-root-quote">
+                <div class="message-meta">
+                    <span class="author">@_threadRootMessage.Author</span>
+                    <span class="timestamp">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
+                </div>
+                <div class="message-content">@_threadRootMessage.Content</div>
+            </div>
+
+            <div class="thread-replies">
+                @if (_threadMessages is not null)
+                {
+                    @foreach (var reply in _threadMessages)
+                    {
+                        <div class="message-bubble thread-reply">
+                            <div class="message-meta">
+                                <span class="author">@reply.Author</span>
+                                <span class="timestamp">@FormatRelativeTime(reply.SentAt)</span>
+                            </div>
+                            <div class="message-content">@reply.Content</div>
+                            @if (reply.Reactions.Count > 0)
+                            {
+                                <div class="reactions-row">
+                                    @foreach (var r in reply.Reactions)
+                                    {
+                                        <button class="reaction-badge" title="@string.Join(", ", r.Users)"
+                                                @onclick="() => ToggleReactionAsync(reply.Id, r.Emoji)">
+                                            @r.Emoji @r.Users.Count
+                                        </button>
+                                    }
+                                </div>
+                            }
+                        </div>
+                    }
+                }
+            </div>
+
+            <div class="message-input-area">
+                <textarea @bind="_threadReplyText" @bind:event="oninput"
+                          @onkeydown="HandleThreadKeyDown"
+                          placeholder="Reply in thread…" rows="2"></textarea>
+                <button class="send-btn" @onclick="SendThreadReplyAsync"
+                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">
+                    Reply
+                </button>
+            </div>
+        </aside>
+    }
+</div>
+
+@code {
+    private const int PageSize = 30;
+    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "👀"];
+
+    // Channels
+    private List<Channel>? _channels;
+    private Channel? _activeChannel;
+    private int? _activeChannelId;
+
+    // Messages
+    private List<Message>? _messages;
+    private Dictionary<int, ThreadSummary> _threadSummaries = new();
+    private int _skip;
+    private bool _loadingOlder;
+    private bool _allOlderLoaded;
+
+    // Thread
+    private bool _threadOpen;
+    private Message? _threadRootMessage;
+    private List<Message>? _threadMessages;
+    private string _threadReplyText = "";
+
+    // Input / UI state
+    private string _newMessageText = "";
+    private int? _hoveredMessageId;
+    private int? _emojiPickerMessageId;
+
+    private ElementReference _messageListRef;
+    private IJSObjectReference? _jsModule;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _channels = await ChatService.GetChannelsAsync();
+    }
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
+                "./_content/sv-4ee42d7cf4cf4db3b00ac9cb55304bf9/Components/Pages/Chat.razor.js");
+        }
+    }
+
+    // ── Channel Selection ──
+
+    private async Task SelectChannelAsync(Channel channel)
+    {
+        _activeChannel = channel;
+        _activeChannelId = channel.Id;
+        _skip = 0;
+        _allOlderLoaded = false;
+        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
+        _skip = _messages.Count;
+        BuildThreadSummaries();
+        await ChatService.MarkChannelReadAsync(channel.Id);
+        UpdateChannelUnread(channel.Id);
+        CloseThread();
+        await ScrollToBottom();
+    }
+
+    private void UpdateChannelUnread(int channelId)
+    {
+        if (_channels is null) return;
+        var idx = _channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
+    }
+
+    // ── Messages ──
+
+    private async Task SendMessageAsync()
+    {
+        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannel is null) return;
+        var sent = await ChatService.SendMessageAsync(_activeChannel.Id, _newMessageText.Trim(), null);
+        _messages ??= new();
+        _messages.Add(sent);
+        _skip++;
+        _newMessageText = "";
+        await ScrollToBottom();
+    }
+
+    private async Task HandleScrollAsync()
+    {
+        if (_loadingOlder || _allOlderLoaded || _activeChannel is null || _jsModule is null) return;
+
+        var scrollTop = await _jsModule.InvokeAsync<double>("getScrollTop", _messageListRef);
+        if (scrollTop < 50)
+        {
+            await LoadOlderMessagesAsync();
+        }
+    }
+
+    private async Task LoadOlderMessagesAsync()
+    {
+        if (_activeChannel is null) return;
+        _loadingOlder = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _skip, PageSize);
+        if (older.Count == 0)
+        {
+            _allOlderLoaded = true;
+        }
+        else
+        {
+            _messages ??= new();
+            _messages.InsertRange(0, older);
+            _skip += older.Count;
+            BuildThreadSummaries();
+        }
+
+        _loadingOlder = false;
+    }
+
+    // ── Thread ──
+
+    private async Task OpenThreadAsync(Message rootMessage)
+    {
+        _threadRootMessage = rootMessage;
+        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
+        _threadReplyText = "";
+        _threadOpen = true;
+        _emojiPickerMessageId = null;
+    }
+
+    private void CloseThread()
+    {
+        _threadOpen = false;
+        _threadRootMessage = null;
+        _threadMessages = null;
+        _threadReplyText = "";
+    }
+
+    private async Task SendThreadReplyAsync()
+    {
+        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannel is null)
+            return;
+
+        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, _threadReplyText.Trim(), _threadRootMessage.Id);
+        _threadMessages ??= new();
+        _threadMessages.Add(reply);
+        _threadReplyText = "";
+        RefreshThreadSummary(_threadRootMessage.Id, reply.SentAt);
+    }
+
+    // ── Reactions ──
+
+    private async Task AddReactionAsync(int messageId, string emoji)
+    {
+        await ChatService.AddReactionAsync(messageId, emoji);
+        _emojiPickerMessageId = null;
+
+        // Refresh messages to show updated reaction
+        if (_activeChannel is not null)
+        {
+            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _skip);
+        }
+        if (_threadRootMessage is not null)
+        {
+            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
+        }
+    }
+
+    private Task ToggleReactionAsync(int messageId, string emoji) => AddReactionAsync(messageId, emoji);
+
+    private void ToggleEmojiPicker(int messageId)
+    {
+        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
+    }
+
+    // ── Thread Summaries ──
+
+    private void BuildThreadSummaries()
+    {
+        _threadSummaries.Clear();
+        if (_messages is null) return;
+
+        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
+        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
+        {
+            _threadSummaries[group.Key] = new ThreadSummary(
+                group.Key,
+                group.Count(),
+                group.Max(m => m.SentAt));
+        }
+    }
+
+    private void RefreshThreadSummary(int rootMessageId, DateTime lastReplyAt)
+    {
+        if (_threadSummaries.TryGetValue(rootMessageId, out var existing))
+        {
+            _threadSummaries[rootMessageId] = existing with
+            {
+                ReplyCount = existing.ReplyCount + 1,
+                LastReplyAt = lastReplyAt
+            };
+        }
+        else
+        {
+            _threadSummaries[rootMessageId] = new ThreadSummary(rootMessageId, 1, lastReplyAt);
+        }
+    }
+
+    // ── Keyboard Shortcuts ──
+
+    private async Task HandleMessageKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+            await SendMessageAsync();
+    }
+
+    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+            await SendThreadReplyAsync();
+    }
+
+    // ── Helpers ──
+
+    private async Task ScrollToBottom()
+    {
+        await Task.Yield();
+        if (_jsModule is not null)
+            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
+    }
+
+    private static string FormatRelativeTime(DateTime sentAt)
+    {
+        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
+        return diff.TotalSeconds switch
+        {
+            < 60 => "just now",
+            < 3600 => $"{(int)diff.TotalMinutes} min ago",
+            < 86400 => $"{(int)diff.TotalHours}h ago",
+            < 604800 => $"{(int)diff.TotalDays}d ago",
+            _ => sentAt.ToString("MMM d, yyyy")
+        };
+    }
+
+    private static string TruncateDescription(string description)
+    {
+        const int maxLen = 40;
+        return description.Length <= maxLen ? description : string.Concat(description.AsSpan(0, maxLen), "…");
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (_jsModule is not null)
+        {
+            await _jsModule.DisposeAsync();
+        }
+    }
+}
